map "http://example.org/fhir/hl7-probes/StructureMap/P03EvaluateD" = `P03EvaluateD`

uses "http://example.org/fhir/hl7-probes/StructureDefinition/Row" alias Row as source
uses "http://hl7.org/fhir/StructureDefinition/Bundle" alias Bundle as target
uses "http://hl7.org/fhir/StructureDefinition/Patient" alias Patient as target

group P03EvaluateD(source src : Row, target bundle : Bundle) {
  src -> bundle.type = 'transaction' "bundle-type";
  src -> bundle.entry as e, e.resource = create('Patient') as res, res.id = evaluate(src, $this.`a1_b`) "r";
}
